def prime_fib(n: int):
    def is_prime(m):
        if m <= 1:
            return False
        if m == 2:
            return True
        if m % 2 == 0:
            return False
        for i in range(3, int(m**0.5) + 1, 2):
            if m % i == 0:
                return False
        return True

    primes = []
    a, b = 1, 1
    while len(primes) < n:
        next_num = a + b
        if is_prime(next_num):
            primes.append(next_num)
        a, b = b, next_num
    return primes[-1]
