def encrypt(s):
    """Encrypts a string by shifting each letter down by 4 places in the alphabet."""
    result = []
    for c in s:
        if c.islower():
            shifted = (ord(c) - ord('a') + 4) % 26
            result.append(chr(shifted + ord('a')))
        else:
            result.append(c)
    return ''.join(result)
