def move_one_ball(arr):
    """Determine if the array can be sorted in non-decreasing order by performing right shifts."""
    if not arr:
        return True

    n = len(arr)
    # Check if already sorted
    is_sorted = True
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            is_sorted = False
            break
    if is_sorted:
        return True

    # Count the number of drop points
    count = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            count += 1

    # Check the conditions for rotation
    if count == 1 and arr[-1] <= arr[0]:
        return True
    else:
        return False
