def match_parens(lst):
    s1, s2 = lst[0], lst[1]
    total_left = s1.count('(') + s2.count('(')
    total_right = s1.count(')') + s2.count(')')

    if total_left != total_right:
        return 'No'

    def is_balanced(s):
        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    else:
        return 'No'
