def tri(n):
    if n == 0:
        return [1]
    res = [1, 3]
    if n == 1:
        return res
    for i in range(2, n + 1):
        if i % 2 == 0:
            val = 1 + (i // 2)
        else:
            val = res[i-1] + res[i-2] + (1 + (i + 1) // 2)
        res.append(val)
    return res
